'use strict';
window.positionDesk=(()=>{
let traders=[],selected='all',platform='all';
const html=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=(x,d=2)=>x===null||x===undefined||x===''?'—':Number(x).toLocaleString('en-US',{maximumFractionDigits:d});
const amount=(v,c,d=2)=>v===null||v===undefined||v===''?'未提供':n(v,d)+(c?' '+html(c):'');
const when=v=>v?new Date(v).toLocaleString('zh-TW',{timeZone:'Asia/Singapore',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}):'尚未讀取';
function metric(label,value,sub='',cls=''){return `<div class="position-metric ${cls}"><span>${label}</span><strong>${value}</strong>${sub?`<small>${sub}</small>`:''}</div>`;}
function card(p,t){let direction=p.direction==='LONG'?'做多':p.direction==='SHORT'?'做空':'方向未提供',short=p.direction==='SHORT',pnl=Number(p.unrealizedPnl),stale=t.positionDetailsStale;let book=p.market==='CM'?'幣本位':'U 本位';const px=p.priceCurrency||'USDT',pc=p.pnlUnit||p.marginUnit;return `<article class="exchange-position ${short?'is-short':'is-long'} ${stale?'is-old':''}"><header class="position-card-head"><div><span class="direction-pill">${direction}</span><strong>${html(p.symbol)}</strong><span class="position-product">${book} · ${html(p.contractType||'永續')}</span></div><div><span class="exchange-tag">${html(p.marginMode||'保證金模式未提供')}</span><span class="leverage-tag">${p.leverage==null?'槓桿未提供':n(p.leverage)+'x'}</span></div></header><div class="position-primary">${metric('倉位價值',amount(p.notionalValue,p.notionalCurrency),html(p.notionalMethod||'交易所未公開金額'))}${metric('持倉數量',amount(p.quantity,p.quantityUnit,8),p.quantityUnit==='張'||p.quantityUnit==='张'?'合約張數':'標的資產數量')}${metric('佔用保證金',amount(p.margin,p.marginUnit,pc==='BTC'?6:2),html(p.marginMode||''))}${metric('未實現盈虧',amount(p.unrealizedPnl,pc,pc==='BTC'?6:2),p.roi==null?'收益率未提供':n(p.roi*100,2)+'%',p.unrealizedPnl==null?'':pnl>=0?'profit':'loss')}</div><div class="position-secondary">${metric('開倉均價',amount(p.entryPrice,px,5))}${metric('標記價格',amount(p.markPrice,px,5))}${metric('預估強平價',amount(p.liquidationPrice,px,5))}${metric('保本價格',amount(p.breakEvenPrice,px,5))}${metric('開倉時倉位金額',amount(p.entryNotional,p.notionalCurrency),p.entryNotional!=null?'數量 × 開倉均價':'')}${metric('保證金比率',p.marginRatio!=null?n(p.marginRatio*100,2)+'%':p.uniMmr!=null?'UniMMR '+n(p.uniMmr):'未提供')}${metric('累計已實現盈虧',amount(p.realizedPnl,pc,pc==='BTC'?6:2))}${metric('手續費 / 資金費',p.fees!=null||p.fundingFees!=null?amount(p.fees,pc)+' / '+amount(p.fundingFees,pc):'未提供')}</div><footer class="position-card-foot"><span>${p.openedAt?'建倉 '+when(p.openedAt):'建倉時間未公開'}</span><span>${stale?'歷史快照':'資料時間'} ${when(t.positionDetailsAt)}</span></footer></article>`;}
function stateLabel(t){let p=t.positionPermission;if(t.platform==='OKX')return t.positionDetailsStale?'資料較舊':'公開實盤';if(p?.stale)return '公開狀態待更新';if(p?.enable===false)return '實盤已關閉';if(p?.sharingPosition===false)return '持倉未公開';return t.positionDetailsStale?'等待最新持倉':'已讀取公開持倉';}
function trader(t){let ps=t.positionDetails||[],last=t.positionDetailsAt,url=t.smartMoneyUrl||t.profileUrl,old=t.positionDetailsStale;let empty=t.platform==='Binance'&&t.positionPermission?.enable===false?'交易員已關閉實盤。':t.platform==='Binance'&&t.positionPermission?.sharingPosition===false?'交易員未公開當前持倉。':t.platform==='OKX'&&!old?'目前公開合約持倉為 0 筆。':t.marketCounts&&!old&&Object.values(t.marketCounts).every(x=>x===0)?'本輪讀頁：U 本位及幣本位均無持倉。':'尚未取得可確認的最新持倉。';let assets=t.platform==='OKX'?(t.assets||[]):[];return `<section class="trader-positions" data-position-owner="${html(t.id)}"><header class="trader-position-head"><div><span class="exchange-label ${t.platform.toLowerCase()}">${html(t.platform)}</span><h2>${html(t.name)}</h2><span class="position-state ${old?'older':''}">${stateLabel(t)}</span></div><a href="${html(url)}" target="_blank" rel="noopener noreferrer">交易所原頁 ↗</a></header><p class="position-source-time">${t.platform==='OKX'?'合約持倉與現貨分開列示':'U 本位與幣本位分開核對'} · ${last?'讀取 '+when(last):'尚無持倉讀取時間'}${t.platform==='Binance'?' · 單次讀頁，尚非連續採集':''}</p>${t.platform==='OKX'?`<div class="portfolio-leverage"><div><span>總體敞口槓桿</span><strong>約 ${n(t.overallExposureLeverage,2)}x</strong></div><div><span>合約總槓桿</span><strong>${n(t.contractGrossLeverage,2)}x</strong></div><div><span>現貨敞口</span><strong>${n(t.spotRiskExposureLeverage,2)}x</strong></div><div><span>淨方向敞口</span><strong>${n(t.netExposureLeverage,2)}x</strong></div></div><p class="portfolio-leverage-note">總敞口按合約多空加現貨占比估算；USDT、USDC 等穩定幣不計入現貨方向敞口。更新 ${when(t.positionDetailsAt)}</p>`:''}${ps.length?(old?`<details class="old-position-details"><summary>查看上次持倉 ${ps.length} 筆（已過期，不能當現倉）</summary>${ps.map(p=>card(p,t)).join('')}</details>`:ps.map(p=>card(p,t)).join('')):`<div class="position-empty">${empty}</div>`}${assets.length?`<details class="spot-details" open><summary>現貨資產 · ${assets.length} 類 <span>現貨方向敞口約 ${n(t.spotRiskExposureLeverage,2)}x</span></summary><div class="spot-grid">${assets.map(a=>`<div class="spot-row"><strong>${html(a.currency)}</strong><div>${n(a.amount,8)} <small>${html(a.currency)}</small></div><span>公開占比 ${n(Number(a.percent)*100,2)}%</span><span>持倉均價 ${amount(a.openAvgPx,'USD',5)}</span></div>`).join('')}</div></details>`:''}</section>`;}
function render(){const host=document.getElementById('position-desk');if(!host)return;let all=traders.filter(t=>t.platform==='OKX'||t.positionPermission),visible=all.filter(t=>(platform==='all'||t.platform===platform)&&(selected==='all'||selected===t.id));const score=t=>(!t.positionDetailsStale&&t.positionDetails?.length?4:!t.positionDetailsStale&&t.assets?.length?3:t.positionDetails?.length?2:1);visible.sort((a,b)=>score(b)-score(a));host.innerHTML=`<div class="position-toolbar"><div><div class="eyebrow">POSITIONS FIRST</div><h2>實盤持倉詳情</h2><p>看方向、倉位金額與保證金；每筆沿用交易所幣種和單位。</p></div><div class="position-filters"><select aria-label="實盤平台" id="position-platform"><option value="all">全部平台</option><option value="Binance">幣安</option><option value="OKX">OKX</option></select><select aria-label="實盤交易員" id="position-trader"><option value="all">全部交易員</option>${all.map(t=>`<option value="${html(t.id)}">${html(t.name)}</option>`).join('')}</select></div></div>${visible.map(trader).join('')||'<div class="position-empty">沒有符合的交易員。</div>'}`;host.querySelector('#position-platform').value=platform;host.querySelector('#position-trader').value=selected;host.querySelector('#position-platform').onchange=e=>{platform=e.target.value;selected='all';render();};host.querySelector('#position-trader').onchange=e=>{selected=e.target.value;render();};}
return {update(data){traders=data.traders;render();},select(id){selected=id;platform='all';render();}};
})();
